def seed_database_taxonomy(db: Session):
    """Seed comprehensive job roles and standardized skills into the database."""
    try:
        # Check existing roles by title for idempotent seeding
        existing_roles = {r.title.lower(): r for r in db.query(JobRole).all()}
        added_roles_count = 0

        for role_data in INITIAL_ROLES:
            if role_data["title"].lower() not in existing_roles:
                role = JobRole(
                    title=role_data["title"],
                    category=role_data["category"],
                    description=role_data["description"],
                    is_custom=False
                )
                db.add(role)
                added_roles_count += 1
            else:
                # Update category and description if existing
                existing_role = existing_roles[role_data["title"].lower()]
                existing_role.category = role_data["category"]
                existing_role.description = role_data["description"]

        db.commit()
        if added_roles_count > 0:
            logger.info(f"Successfully seeded {added_roles_count} new job roles. Total roles: {db.query(JobRole).count()}")

        # Check existing skills by name
        existing_skills = {s.name.lower(): s for s in db.query(Skill).all()}
        added_skills_count = 0
        for skill_data in INITIAL_SKILLS:
            if skill_data["name"].lower() not in existing_skills:
                skill = Skill(
                    name=skill_data["name"],
                    category=skill_data["category"]
                )
                db.add(skill)
                added_skills_count += 1

        db.commit()
        if added_skills_count > 0:
            logger.info(f"Successfully seeded {added_skills_count} new skills.")

    except Exception as e:
        db.rollback()
        logger.error(f"Error seeding database taxonomy: {e}")
